<script setup lang="ts">
import {signOut} from './access';
import {UiBadge,UiButton,UiMetric,UiPanel,UiSelect,UiInput,UiTabs,UiSwitch,UiEmptyState,UiDialog} from './components/ui';
import {computed,ref,watch,onMounted,onBeforeUnmount,defineAsyncComponent} from 'vue';
import {campuses} from './campus';
import KnowledgeDetail from './components/KnowledgeDetail.vue';
import PresentationViewer from './components/PresentationViewer.vue';
import {findTopic,type Dossier,type KnowledgeLink} from './knowledge';
import InstituteBadge from './components/InstituteBadge.vue';
import { instituteIdentity, instituteStyle, campusInstitutes } from './identity';
import PageControls from './components/PageControls.vue';
import DonutChart from './components/DonutChart.vue';
import Icon from './components/Icon.vue';import LineChart from './components/LineChart.vue';import Admissions from './components/Admissions.vue';import CalendarView from './components/Calendar.vue';import Analytics from './components/Analytics.vue';
import {institutes,objects,moscowObjects,overview as o,admissions as a,events,projects,science,fmt,type Institute,type CampusObject,type UniversityEvent} from './data';
import kpiChartArea from './assets/kpi-card/chart-area.svg';
import kpiChartLine from './assets/kpi-card/chart-line.svg';
import kpiChartPoint from './assets/kpi-card/chart-point.svg';
import kpiDescriptionBullet from './assets/kpi-card/description-bullet.svg';
import kpiUsersIcon from './assets/kpi-card/users.svg';
const overviewSeries=ref<'score'|'enrolled'>('score');
const DesignSystem=defineAsyncComponent(()=>import('./components/DesignSystem.vue'));
const InfrastructureMap=defineAsyncComponent(()=>import('./components/InfrastructureMap.vue'));
const CampusMap=defineAsyncComponent(()=>import('./components/CampusMap.vue'));
const nav=[{id:'home',name:'Обзор университета'},{id:'university',name:'Университет'},{id:'map',name:'Карта инфраструктуры'},{id:'admissions',name:'Приёмная кампания'},{id:'calendar',name:'Календарь событий'},{id:'institutes',name:'Институты и академии'},{id:'science',name:'Наука и разработки'},{id:'finance',name:'Финансы'},{id:'projects',name:'Проекты развития'},{id:'design',name:'Дизайн-система'}];
const page=ref('home');const sidebar=ref(false);const navCollapsed=ref(localStorage.getItem('erut-nav-collapsed')==='true');watch(navCollapsed,v=>localStorage.setItem('erut-nav-collapsed',String(v)));const admissionContext=ref('all');const notifications=ref(false);const notificationsRead=ref(false);const config=ref(false);const toast=ref('');let toastTimer:ReturnType<typeof setTimeout>;
const sourcePage=ref<number|null>(null);const selectedInstitute=ref<Institute|null>(null);const selectedObject=ref<CampusObject|null>(null);const selectedEvent=ref<UniversityEvent|null>(null);const selectedTopic=ref<Dossier|null>(null);const topicInitialSection=ref(0);const detailTab=ref('overview');const mapCategory=ref('Все объекты');const mapQuery=ref('');const mapFocus=ref('');const mapFocusSequence=ref(0);const instituteQuery=ref('');const projectCategory=ref('Все проекты');
const widgetsMeta=[{id:'admissions',title:'Приёмная кампания'},{id:'map',title:'Инфраструктура'},{id:'students',title:'Контингент по институтам'},{id:'events',title:'Ближайшие события'},{id:'science',title:'Наука и исследования'},{id:'projects',title:'В фокусе внимания'}];
const defaultWidgets=()=>widgetsMeta.map(w=>({...w,visible:!['science','projects'].includes(w.id),wide:false}));
function loadWidgets(){try{const x=JSON.parse(localStorage.getItem('erut-widgets-v2')||'null');if(Array.isArray(x)&&x.length===widgetsMeta.length&&widgetsMeta.every(w=>x.some(i=>i.id===w.id)))return x as ReturnType<typeof defaultWidgets>;}catch{}return defaultWidgets();}
const widgets=ref(loadWidgets());const dragging=ref<string|null>(null);watch(widgets,v=>localStorage.setItem('erut-widgets-v2',JSON.stringify(v)),{deep:true});
const shownWidgets=computed(()=>widgets.value.filter(w=>w.visible));const pageTitle=computed(()=>nav.find(n=>n.id===page.value)?.name||'Обзор университета');
const overviewPage=ref(0);const institutePage=ref(0);const projectPage=ref(0);
const narrowScreen=ref(window.matchMedia('(max-width: 760px)').matches);
const catalogSize=computed(()=>narrowScreen.value?2:4);
const widgetGroups=computed(()=>{
 const groups:typeof shownWidgets.value[]=[];let group:typeof shownWidgets.value=[];
 for(const widget of shownWidgets.value){
  if(widget.wide||narrowScreen.value){if(group.length)groups.push(group);groups.push([widget]);group=[];}
  else {group.push(widget);if(group.length===2){groups.push(group);group=[];}}
 }
 if(group.length)groups.push(group);return groups;
});
const focusedWidgets=computed(()=>config.value?shownWidgets.value:widgetGroups.value[overviewPage.value]||[]);
const widgetGroupTitle=(group:typeof shownWidgets.value)=>group.map(w=>({admissions:'Приём',map:'Карта',students:'Институты',events:'События',science:'Наука',projects:'Проекты'}[w.id]||w.title)).join(' и ');
watch(widgetGroups,()=>{overviewPage.value=Math.min(overviewPage.value,Math.max(0,widgetGroups.value.length-1));});
watch([instituteQuery,projectCategory,narrowScreen],()=>{institutePage.value=0;projectPage.value=0;});
function resizeWorkspace(){narrowScreen.value=window.matchMedia('(max-width: 760px)').matches;}
onMounted(()=>window.addEventListener('resize',resizeWorkspace));onBeforeUnmount(()=>window.removeEventListener('resize',resizeWorkspace));
const objectColleges=computed(()=>a.college.institutes.filter(c=>c.objectIds.includes(selectedObject.value?.id||'')));
const objectRows=computed(()=>moscowObjects.filter(i=>(mapCategory.value==='Все объекты'||i.category===mapCategory.value)&&(i.name+' '+i.address).toLowerCase().includes(mapQuery.value.toLowerCase())));
const instituteRows=computed(()=>institutes.filter(i=>(i.name+' '+i.short).toLowerCase().includes(instituteQuery.value.toLowerCase())));
const projectRows=computed(()=>projects.filter(i=>projectCategory.value==='Все проекты'||i.category===projectCategory.value));
const topInstitutes=computed(()=>[...institutes].sort((a,b)=>b.students-a.students).slice(0,5));
function notify(t:string){toast.value=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3500);}
function collapseNavigation(){if(!narrowScreen.value)navCollapsed.value=true;}
function focusObject(object:CampusObject){mapFocus.value=object.id;mapFocusSequence.value++;collapseNavigation();if(narrowScreen.value)document.querySelector('.large-map')?.scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function go(id:string){if(id!=='home')collapseNavigation();overviewPage.value=0;institutePage.value=0;projectPage.value=0;config.value=false;page.value=id;location.hash='/'+id;sidebar.value=false;notifications.value=false;window.scrollTo({top:0,behavior:'auto'});}
function hashChange(){const id=location.hash.replace('#/','');page.value=nav.some(n=>n.id===id)?id:'home';}
function logout(){signOut();}
type DetailFrame={institute:Institute|null;object:CampusObject|null;event:UniversityEvent|null;topic:Dossier|null;tab:string;section:number;title:string};
const detailTrail=ref<DetailFrame[]>([]);
function snapshot():DetailFrame{return {institute:selectedInstitute.value,object:selectedObject.value,event:selectedEvent.value,topic:selectedTopic.value,tab:detailTab.value,section:topicInitialSection.value,title:selectedInstitute.value?.short||selectedObject.value?.name||selectedEvent.value?.title||selectedTopic.value?.title||''};}
function clearDetail(){selectedInstitute.value=null;selectedObject.value=null;selectedEvent.value=null;selectedTopic.value=null;sourcePage.value=null;}
function descend(){collapseNavigation();const frame=snapshot();if(frame.title)detailTrail.value.push(frame);clearDetail();detailTab.value='overview';topicInitialSection.value=0;}
function openInstitute(i:Institute){descend();selectedInstitute.value=i;}
function openObject(i:CampusObject){descend();selectedObject.value=i;}
function openEvent(e:UniversityEvent){descend();selectedEvent.value=e;}
function openTopic(id:string,section=0){const topic=findTopic(id);if(!topic)return;descend();selectedTopic.value=topic;topicInitialSection.value=section;}
function backDetail(){const frame=detailTrail.value.pop();if(!frame)return;clearDetail();selectedInstitute.value=frame.institute;selectedObject.value=frame.object;selectedEvent.value=frame.event;selectedTopic.value=frame.topic;detailTab.value=frame.tab;topicInitialSection.value=frame.section;}
function closeModal(){clearDetail();detailTrail.value=[];}
function followLink(link:KnowledgeLink){if(link.kind==='topic')openTopic(link.id);else if(link.kind==='institute'){const i=institutes.find(i=>i.id===link.id);if(i)openInstitute(i);}else if(link.kind==='object'){const o=objects.find(o=>o.id===link.id);if(o)openObject(o);}else{closeModal();go(link.id);}}
function openAdmissions(id='all'){admissionContext.value=id;closeModal();go('admissions');}
function showOnMap(object:CampusObject){closeModal();mapFocus.value=object.id;mapQuery.value='';mapCategory.value='Все объекты';go('map');}
function openProgram(program:{name:string;institute:string;value?:number;metric?:string;level?:string}){
 const college=a.college.institutes.some(i=>i.short===program.institute);
 const institute=institutes.find(i=>i.short===program.institute);
 const related=college?{label:'Карточка колледжа',id:'college-'+program.institute,kind:'topic' as const}:institute?{label:institute.name,id:institute.id,kind:'institute' as const}:null;
 const matches=[...a.programs,...a.college.programs].filter(p=>!!program.metric&&p.metric===program.metric&&p.name===program.name&&p.institute===program.institute);
 const labels:Record<string,string>={applications:'Заявлений',competition:'Конкурс · чел./место',score:'Средний балл ЕГЭ'};
 descend();selectedTopic.value={id:'program-'+program.name,title:program.name,summary:program.level||('Приёмная кампания 2026 · '+(college?'среднее профессиональное':'высшее')+' образование'),metrics:matches.map(p=>({label:labels[p.metric],value:fmt(p.value)})),sections:[{title:'Профиль программы',rows:[{label:'Подразделение',value:program.institute,description:'',...(college?{topic:'college-'+program.institute}:{institute:institute?.id})},{label:'Период',value:'2026',description:program.level?'Новая образовательная программа.':'Показатель относится к соответствующему рейтингу приёмной кампании. Не является проходным баллом или планом набора.'}]}],related:related?[related]:[],source:college?7:6};
}
function drop(id:string){if(!dragging.value||id===dragging.value)return;const from=widgets.value.findIndex(w=>w.id===dragging.value);const to=widgets.value.findIndex(w=>w.id===id);const [w]=widgets.value.splice(from,1);widgets.value.splice(to,0,w);dragging.value=null;}
function reorder(id:string,offset:number){const index=widgets.value.findIndex(w=>w.id===id);const dest=index+offset;if(dest<0||dest>=widgets.value.length)return;const [w]=widgets.value.splice(index,1);widgets.value.splice(dest,0,w);}
const modalOpen=computed(()=>!!(sourcePage.value||selectedInstitute.value||selectedObject.value||selectedEvent.value||selectedTopic.value));
function keydown(e:KeyboardEvent){if(e.key==='Escape'){config.value=false;notifications.value=false;sidebar.value=false;}}
function outsidePopover(event:PointerEvent){const target=event.target as Element;if(!target.closest('.notifications-popover,.notification-button'))notifications.value=false;}
onMounted(()=>{document.addEventListener('pointerdown',outsidePopover);hashChange();window.addEventListener('hashchange',hashChange);window.addEventListener('keydown',keydown);});onBeforeUnmount(()=>{document.removeEventListener('pointerdown',outsidePopover);window.removeEventListener('hashchange',hashChange);window.removeEventListener('keydown',keydown);clearTimeout(toastTimer);});
</script>
<template>
<div class="app-shell" :class="{'nav-collapsed':navCollapsed}"><div v-if="sidebar" class="sidebar-scrim" @click="sidebar=false"></div><aside class="sidebar" :class="{open:sidebar}"><UiButton class="brand" aria-label="RUT.digital · обзор университета" title="Обзор университета" @click="go('home')"><img :src="'./favicon.svg'" alt=""/><span>RUT.digital<span class="brand-dot">.</span></span></UiButton><div class="university-label">Университет транспорта</div><nav><UiButton v-for="(n,i) in nav.filter(n=>n.id!=='design')" :key="n.id" :aria-label="n.name" :title="navCollapsed?n.name:undefined" :aria-current="page===n.id?'page':undefined" :class="{active:page===n.id,'nav-separator':n.id==='institutes'}" @click="go(n.id)"><Icon :name="n.id==='university'?'book':n.id" :size="19"/><span>{{n.name}}</span><span v-if="n.id==='calendar'" class="nav-count">{{events.length}}</span><span v-if="page===n.id" class="active-dot"></span></UiButton></nav><div class="sidebar-bottom"><div class="anniversary-mini"><span class="mini-number">130</span><div>лет в движении<small>1896 — 2026</small></div><Icon name="sparkles"/></div><UiButton class="source-nav" aria-label="О презентации" title="О презентации" @click="closeModal();sourcePage=1"><Icon name="source"/><span>О презентации</span><Icon name="arrow" :size="15"/></UiButton><UiButton class="source-nav design-nav" aria-label="Дизайн-система" title="Дизайн-система" :class="{active:page==='design'}" :aria-current="page==='design'?'page':undefined" @click="go('design')"><Icon name="design"/><span>Дизайн-система</span><Icon name="arrow" :size="15"/></UiButton><div class="profile"><div class="avatar">Р</div><div><b>Учётная запись</b><small>Оператор</small></div><UiButton class="icon-btn" title="Выйти" aria-label="Выйти" @click="logout"><Icon name="logout" :size="17"/></UiButton></div></div></aside>
<div class="main-shell"><header class="topbar"><UiButton class="nav-toggle" :aria-label="narrowScreen?(sidebar?'Скрыть навигацию':'Показать навигацию'):(navCollapsed?'Показать навигацию':'Скрыть навигацию')" :aria-expanded="narrowScreen?sidebar:!navCollapsed" @click="narrowScreen?sidebar=!sidebar:navCollapsed=!navCollapsed"><Icon name="menu"/></UiButton><div class="breadcrumb"><b>{{pageTitle}}</b></div><div class="topbar-actions"><UiButton class="icon-btn notification-button" aria-label="Уведомления" :aria-expanded="notifications" @click="notifications=!notifications"><Icon name="bell"/><i v-if="!notificationsRead"></i></UiButton><div class="avatar small">Р</div></div><div v-if="notifications" class="notifications-popover"><div class="popover-heading">В фокусе · сентябрь 2026<UiButton class="icon-btn" title="Отметить прочитанными" @click="notificationsRead=true;notify('Отмечено прочитанным')"><Icon name="read"/></UiButton></div><UiButton @click="openTopic('trustees');notifications=false"><UiBadge class="badge orange">Требует внимания</UiBadge><b>Актуализация попечительского совета</b><small>Управление университетом</small></UiButton><UiButton @click="openTopic('bas');notifications=false"><UiBadge class="badge">Проект передачи</UiBadge><b>Цифровой реестр кадров БАС</b><small>Контракты сопровождения истекают в декабре 2026</small></UiButton><p>Статусы на сентябрь 2026 года.</p></div></header>
<main class="focus-main"><div v-if="page!=='admissions'" class="page-heading"><div><h1>{{pageTitle}}<span v-if="page==='home'" class="heading-dot"></span></h1><p>{{page==='home'?'Основные показатели университета.':page==='map'?'Выберите кампус для просмотра зданий и сервисов.':page==='admissions'?'Итоги приёмной кампании 2026.':page==='calendar'?'Календарь университета.':page==='institutes'?'Единые карточки подразделений и связанные показатели.':page==='science'?'Исследования и научные программы.':page==='finance'?'Ресурсы университета и приоритеты развития.':'Проекты университета.'}}</p></div><div class="heading-actions"><span v-if="page!=='design'" class="period-pill"><Icon name="calendar" :size="15"/>Сентябрь 2026</span><UiButton v-if="page==='home'" class="btn" :class="{selected:config}" @click="config=!config"><Icon name="settings" :size="16"/>Настроить обзор</UiButton></div></div>
<div class="page-workspace" :class="'workspace-'+page"><template v-if="page==='home'">
<div class="kpi-grid home-kpis"><UiMetric interactive class="kpi kpi-card--featured" @click="go('university')"><template #heading><img class="kpi-card__chart-area" :src="kpiChartArea" alt=""/><img class="kpi-card__chart-line" :src="kpiChartLine" alt=""/><img class="kpi-card__chart-point" :src="kpiChartPoint" alt=""/><span class="kpi-card__heading">Обучающихся <img :src="kpiUsersIcon" alt=""/></span></template><template #content><strong>{{fmt(o.students)}}</strong><span class="kpi-card__trend">↗ +4,2%</span></template><template #detail><small class="kpi-card__description"><img :src="kpiDescriptionBullet" alt=""/>ВО, СПО и гимназия</small><small class="kpi-card__comparison">к 2025 году</small></template></UiMetric><UiMetric interactive class="kpi" @click="go('admissions')"><template #heading><span>{{narrowScreen?'Зачислено · 2026':'Зачислено в 2026 · ВО'}} <Icon name="admissions"/></span></template><template #content><strong>{{fmt(a.enrolled)}}<svg class="spark" viewBox="0 0 100 35"><path d="M0 24L30 32L68 4L100 10"/></svg></strong></template><template #detail><small><b class="positive">+28%</b> {{narrowScreen?'заявлений':'заявлений к 2025 году'}}</small></template></UiMetric><UiMetric interactive class="kpi" @click="openTopic('admission-quality')"><template #heading><span>Средний балл ЕГЭ <Icon name="trend"/></span></template><template #content><strong>{{fmt(a.score)}}<svg class="spark" viewBox="0 0 100 35"><path d="M0 33L30 27L65 17L100 2"/></svg></strong></template><template #detail><small><b class="positive">↗ +5,7</b> {{narrowScreen?'· бюджет':'балла · бюджет'}}</small></template></UiMetric><UiMetric interactive class="kpi" @click="go('science')"><template #heading><span>{{narrowScreen?'НИОКР · план':'Объём НИОКР · план'}} <Icon name="science"/></span></template><template #content><strong>{{(science.total/1000).toLocaleString('ru-RU')}} <em>млрд ₽</em></strong></template><template #detail><small><b class="positive">×2</b> {{narrowScreen?'за 2024–2026':'за 2024–2026 годы'}}</small></template></UiMetric></div>
<div v-if="config" class="config-panel"><div class="panel-head"><div><h2>Ваш обзор — ваши приоритеты</h2><p>Перетаскивайте блоки за верхнюю панель, меняйте ширину и состав.</p></div><UiButton class="btn" @click="widgets=defaultWidgets();notify('Стандартный обзор восстановлен')"><Icon name="reset" :size="16"/>Сбросить</UiButton></div><div class="widget-options"><UiSwitch v-for="w in widgets" :key="w.id" v-model="w.visible" :label="w.title"/></div></div>
<UiTabs v-if="!config && widgetGroups.length>1" v-model="overviewPage" :items="widgetGroups.map((group,index)=>({value:index,label:widgetGroupTitle(group)}))" label="Блоки обзора"/><div class="dashboard-grid" :class="{'dashboard-editing':config,'single-widget':focusedWidgets.length===1}"><UiPanel v-for="w in focusedWidgets" :key="w.id" class="panel widget" :class="{'widget-wide':w.wide,'is-dragging':dragging===w.id, ['widget-'+w.id]:true}" @dragover.prevent @drop.prevent="drop(w.id)"><div class="widget-dragbar" :draggable="true" @dragstart="dragging=w.id" @dragend="dragging=null"><span><Icon name="grip" :size="14"/>{{w.title.toUpperCase()}}</span><div v-if="config" class="widget-tools"><UiButton title="Переместить выше" :disabled="widgets.findIndex(item=>item.id===w.id)===0" class="icon-btn" @click="reorder(w.id,-1)"><Icon name="up" :size="14"/></UiButton><UiButton title="Переместить ниже" :disabled="widgets.findIndex(item=>item.id===w.id)===widgets.length-1" class="icon-btn" @click="reorder(w.id,1)"><Icon name="downArrow" :size="14"/></UiButton><UiButton title="Изменить ширину" class="icon-btn" @click="w.wide=!w.wide"><Icon name="expand" :size="14"/></UiButton><UiButton title="Скрыть блок" class="icon-btn" @click="w.visible=false"><Icon name="close" :size="14"/></UiButton></div><UiButton v-else class="icon-btn" :aria-label="'Открыть '+w.title" @click="go(w.id==='students'?'institutes':w.id==='events'?'calendar':w.id)"><Icon name="arrow" :size="17"/></UiButton></div>
<template v-if="w.id==='admissions'"><div class="widget-body"><div class="panel-head"><div><h2>{{overviewSeries==='score'?'Качество приёма':'Динамика зачисления'}}</h2><p>{{overviewSeries==='score'?'Средний балл ЕГЭ · бюджет':'Зачислено на все формы обучения'}}</p></div><div class="segmented chart-switch"><UiButton :class="{active:overviewSeries==='score'}" @click="overviewSeries='score'">Балл ЕГЭ</UiButton><UiButton :class="{active:overviewSeries==='enrolled'}" @click="overviewSeries='enrolled'">Приём</UiButton></div></div><div class="chart-headline"><strong>{{fmt(overviewSeries==='score'?a.score:a.enrolled)}}</strong><UiBadge class="badge" :class="overviewSeries==='score'?'green':''">{{overviewSeries==='score'?'+5,7 к 2025':'Итог кампании'}}</UiBadge></div><LineChart :key="overviewSeries" :values="overviewSeries==='score'?a.scoreHistory:a.enrollmentHistory" :labels="a.years"/><div class="widget-bottom"><span><i class="dot"></i>Российский университет транспорта</span><UiButton @click="go('admissions')">Аналитика приёма <Icon name="right" :size="14"/></UiButton></div></div></template>
<template v-else-if="w.id==='map'"><div class="widget-body map-widget-head"><div><h2>Университет на карте</h2><p>{{campuses.length}} кампусов · Москва и Сочи</p></div><UiBadge class="badge">Инфраструктура</UiBadge></div><div class="mini-map"><CampusMap compact @campus="id=>{mapFocus=id;go('map')}"/><UiButton class="mini-map-open" @click="go('map')"><Icon name="expand" :size="15"/>Открыть карту</UiButton></div></template>
<template v-else-if="w.id==='students'"><div class="widget-body"><div class="panel-head"><div><h2>Контингент по институтам</h2><p>Очная форма обучения · топ-5</p></div><UiButton class="subtle-link" @click="go('institutes')">Все 10 <Icon name="chevron" :size="14"/></UiButton></div><div class="institute-bars"><UiButton v-for="i in topInstitutes" :key="i.id" :style="instituteStyle(i.id)" @click="openInstitute(i)"><InstituteBadge :id="i.id"/><span class="bar-track"><span :style="{width:i.students/7551*100+'%'}"></span></span><b>{{fmt(i.students)}}</b><Icon name="chevron" :size="14"/></UiButton></div></div></template>
<template v-else-if="w.id==='events'"><div class="widget-body"><div class="panel-head"><div><h2>Календарь движения</h2><p>События к 130-летию университета</p></div><UiButton class="subtle-link" @click="go('calendar')">Календарь <Icon name="chevron" :size="14"/></UiButton></div><UiButton class="upcoming-event" v-for="e in [events[0],events[2],events[3]]" :key="e.id" @click="openEvent(e)"><div class="date-tile"><b>{{e.start?.slice(8)}}</b><span>СЕН</span></div><div><b>{{e.title}}</b><small><i class="event-dot" :class="e.category==='Строительство'?'teal':''"></i>{{e.category}}</small></div><Icon name="arrow" :size="16"/></UiButton></div></template>
<template v-else-if="w.id==='science'"><div class="widget-body"><div class="panel-head"><div><h2>Наука с перспективой</h2><p>Объём НИОКР · млрд ₽</p></div><UiBadge class="badge">План 2026</UiBadge></div><div class="science-home"><div class="science-bars"><div v-for="(v,i) in science.volumes" :key="i"><b>{{fmt(v)}}</b><span :style="{height:v/2.9*90+'px'}"></span><small>{{science.years[i]}}</small></div></div><div class="science-target"><Icon name="trend" :size="24"/><b>&gt; 10 <small>млрд ₽</small></b><p>целевой объём<br>к 2036 году</p></div></div></div></template>
<template v-else><div class="widget-body"><div class="panel-head"><div><h2>В фокусе внимания</h2><p>Ключевые вопросы из отчёта</p></div><UiBadge class="badge orange">2 вопроса</UiBadge></div><UiButton class="focus-item" @click="openTopic('bas')"><span class="focus-icon"><Icon name="projects"/></span><div><b>Передача цифрового реестра БАС</b><small>Переход прав · 1 апреля 2027</small></div><Icon name="arrow" :size="16"/></UiButton><UiButton class="focus-item" @click="openTopic('trustees')"><span class="focus-icon orange"><Icon name="users"/></span><div><b>Попечительский совет</b><small>Требует актуализации</small></div><Icon name="arrow" :size="16"/></UiButton><UiButton class="full-link" @click="go('projects')">Все проекты развития <Icon name="right" :size="15"/></UiButton></div></template></UiPanel></div><div v-if="!shownWidgets.length" class="panel empty">Все блоки скрыты. Верните нужные через «Настроить обзор».</div></template>
<template v-else-if="page==='map'"><InfrastructureMap @navigate="go" @admissions="openAdmissions" @object="id=>{const object=objects.find(o=>o.id===id);if(object)openObject(object)}" :initial-campus-id="mapFocus" @campus="id=>{mapFocus=id;collapseNavigation()}" @institute="id=>{const institute=institutes.find(i=>i.id===id);if(institute)openInstitute(institute)}"/></template>
<DesignSystem v-else-if="page==='design'" @institute="openInstitute" @topic="openTopic"/>
<KnowledgeDetail v-else-if="page==='university'" :topic="findTopic('university')!" embedded @navigate="followLink"/><Admissions v-else-if="page==='admissions'" :initial-institute="admissionContext" @institute="openInstitute" @topic="openTopic" @program="openProgram"/>
<CalendarView v-else-if="page==='calendar'" @event="openEvent"/>
<template v-else-if="page==='institutes'"><div class="page-toolbar"><div class="section-description"><b>10 подразделений</b><span>Очная форма · данные приёмной кампании</span></div><UiInput v-model="instituteQuery" placeholder="Найти институт" aria-label="Найти институт"><template #prefix><Icon name="search" :size="16"/></template></UiInput></div><div class="institute-grid"><UiButton v-for="i in instituteRows.slice(institutePage*catalogSize,(institutePage+1)*catalogSize)" :key="i.id" class="institute-card" :style="instituteStyle(i.id)" @click="openInstitute(i)"><div class="institute-card-cover"><img :src="objects.find(o=>o.id===i.objectId)?.image" alt=""/><InstituteBadge :id="i.id" large/><Icon class="institute-watermark" :name="instituteIdentity(i.id).icon" :size="120"/><Icon class="institute-card-arrow" name="arrow"/></div><div class="institute-card-body"><h2>{{i.name}}</h2><div class="institute-card-stats"><div><b>{{fmt(i.students)}}</b><small>студентов · очно</small></div><div><b>{{fmt(i.enrolled)}}</b><small>зачислено в 2026</small></div></div></div></UiButton></div><PageControls v-model:page="institutePage" :total="instituteRows.length" :size="catalogSize" label="Страницы институтов"/><UiEmptyState v-if="!instituteRows.length" title="Подразделения не найдены" description="Попробуйте название или сокращение института."><UiButton variant="secondary" @click="instituteQuery=''">Сбросить поиск</UiButton></UiEmptyState></template>
<Analytics v-else-if="page==='science'||page==='finance'" :key="page" :page="page" @topic="openTopic"/>
<template v-else-if="page==='projects'"><div class="chips"><UiButton v-for="c in ['Все проекты',...new Set(projects.map(p=>p.category))]" :key="c" :class="{active:projectCategory===c}" @click="projectCategory=c">{{c}}</UiButton></div><div class="project-grid"><UiButton v-for="(p,i) in projectRows.slice(projectPage*catalogSize,(projectPage+1)*catalogSize)" :key="p.id" class="project-card" @click="openTopic(p.id)"><div class="project-card-top"><span class="project-index">{{String(projectPage*catalogSize+i+1).padStart(2,'0')}}</span><UiBadge class="badge" :class="p.id==='trustees'?'orange':''">{{p.status}}</UiBadge><Icon name="arrow"/></div><span class="eyebrow">{{p.category}}</span><h2>{{p.title}}</h2><p>{{p.description}}</p><div class="project-card-footer"><b>{{p.metric}}</b><span>Открыть проект <Icon name="right" :size="14"/></span></div></UiButton></div><PageControls v-model:page="projectPage" :total="projectRows.length" :size="catalogSize" label="Страницы проектов"/></template></div>
<footer v-if="page!=='design'" class="page-footer"><span><i class="dot"></i>Состояние на сентябрь 2026</span><span>RUT.digital · РУТ (МИИТ)</span></footer></main></div></div>
<Transition name="toast"><div v-if="toast" class="toast-message" role="status"><Icon name="check" :size="18"/>{{toast}}</div></Transition>
<UiDialog :open="modalOpen" :label="sourcePage?'Презентация':selectedInstitute?.name||selectedObject?.name||selectedEvent?.title||selectedTopic?.title||'Карточка'" :style="selectedInstitute&&!sourcePage?instituteStyle(selectedInstitute.id):{}" :class="{'source-modal':sourcePage,'object-modal':selectedObject&&!sourcePage,'institute-modal':selectedInstitute&&!sourcePage,'event-modal':selectedEvent&&!sourcePage,'topic-dialog':selectedTopic&&!sourcePage}" @close="closeModal">
<UiButton v-if="detailTrail.length&&!sourcePage" class="detail-back" @click="backDetail"><Icon name="left" :size="18"/><span>Назад · {{detailTrail.at(-1)?.title}}</span></UiButton>
<PresentationViewer v-if="sourcePage" :model-value="sourcePage" @update:model-value="sourcePage=$event"/>
<KnowledgeDetail v-else-if="selectedTopic" :key="selectedTopic.id" :topic="selectedTopic" :initial-section="topicInitialSection" @section="topicInitialSection=$event" @navigate="followLink"/>
<template v-else-if="selectedObject"><div class="object-cover"><img :src="selectedObject.image" :alt="selectedObject.name"/><UiBadge class="badge">{{selectedObject.category}}</UiBadge></div><div class="modal-body"><span class="eyebrow">ИНФРАСТРУКТУРА · РУТ (МИИТ)</span><h2>{{selectedObject.name}}</h2><p class="location-line"><Icon name="pin" :size="16"/>{{selectedObject.address}}</p><div v-if="selectedObject && campusInstitutes(selectedObject.id).length" class="campus-identities object-institute-links"><UiButton v-for="i in campusInstitutes(selectedObject.id)" :key="i.id" @click="openInstitute(i)"><InstituteBadge :id="i.id"/><Icon name="arrow" :size="16"/></UiButton></div><UiTabs v-model="detailTab" class="detail-tabs" label="Разделы карточки" :items="[{value:'overview',label:'Обзор'},{value:'institutes',label:'Подразделения'},{value:'video',label:'Видео'}]"/><template v-if="detailTab==='overview'"><div class="detail-stats"><div><b>{{selectedObject.students?fmt(selectedObject.students):'—'}}</b><span>обучающихся{{selectedObject.students&&selectedObject.students%100===0?' · округлённо':''}}</span></div><div><b>{{selectedObject.buildings}}</b><span>корпусов</span></div><div><b>{{fmt(selectedObject.area)}}<small>м²</small></b><span>площадь</span></div></div><details class="data-note"><summary>О точности данных</summary><p>Расположение приблизительное, по улице. Характеристики корпуса и контингент института могут отличаться по охвату и форме обучения.</p></details><UiButton class="btn" @click="showOnMap(selectedObject)"><Icon name="map" :size="16"/>Показать на карте</UiButton></template><template v-else-if="detailTab==='institutes'"><UiButton class="linked-institute" :style="instituteStyle(i.id)" v-for="i in institutes.filter(i=>i.objectId===selectedObject?.id)" :key="i.id" @click="openInstitute(i)"><InstituteBadge :id="i.id"/><b>{{i.name}}</b><Icon name="arrow"/></UiButton><UiButton class="linked-institute" v-for="c in objectColleges" :key="c.short" @click="openTopic('college-'+c.short)"><Icon name="book"/><b>{{c.short}} · среднее профессиональное образование</b><Icon name="arrow"/></UiButton><p class="empty" v-if="!institutes.some(i=>i.objectId===selectedObject?.id)&&!objectColleges.length">Для этого объекта отдельная карточка института в данных приёмной кампании отсутствует.</p></template><div v-else class="video-placeholder"><div class="video-grid"></div><Icon name="video" :size="42"/><h3>Трансляция не подключена</h3><p>Источник видеосигнала не подключён.<br></p><UiBadge class="badge">Нет источника сигнала</UiBadge></div><div class="detail-actions"><UiButton v-for="c in objectColleges" :key="c.short" variant="secondary" @click="openTopic('college-'+c.short)">{{c.short}} · программы и приём <Icon name="right"/></UiButton><UiButton v-if="selectedObject.id.startsWith('school')" variant="secondary" @click="openTopic('gymnasium')">Гимназия: обучение и достижения <Icon name="right"/></UiButton><UiButton v-if="selectedObject.id==='military'" variant="secondary" @click="openEvent(events.find(e=>e.id==='military')!)">Открытие учебного центра <Icon name="calendar"/></UiButton></div></div></template>
<template v-else-if="selectedInstitute"><div class="institute-modal-header"><InstituteBadge :id="selectedInstitute.id" large/><Icon class="institute-header-watermark" :name="instituteIdentity(selectedInstitute.id).icon" :size="210"/><div><span class="eyebrow">КАРТОЧКА ПОДРАЗДЕЛЕНИЯ</span><h2>{{selectedInstitute.name}}</h2></div></div><div class="modal-body"><UiTabs v-model="detailTab" class="detail-tabs" label="Разделы карточки" :items="[{value:'overview',label:'Обзор'},{value:'admissions',label:'Приём'},{value:'campus',label:'Инфраструктура'}]"/><div v-if="detailTab!=='campus'" class="detail-stats"><div><b>{{fmt(selectedInstitute.students)}}</b><span>студентов · очно</span></div><div><b>{{fmt(selectedInstitute.enrolled)}}</b><span>зачислено в 2026 · очно</span></div><div><b>{{fmt(selectedInstitute.enrolled/selectedInstitute.students*100)}}<small>%</small></b><span>доля нового набора · расчёт</span></div></div><template v-if="detailTab==='overview'"><div class="institute-overview-grid"><UiPanel class="panel"><h3>Состав контингента</h3><DonutChart :items="[{name:'Набор 2026',value:selectedInstitute.enrolled,color:instituteIdentity(selectedInstitute.id).color},{name:'Остальной контингент',value:selectedInstitute.students-selectedInstitute.enrolled,color:instituteIdentity(selectedInstitute.id).color+'45'}]" label="студентов · очно"/></UiPanel><UiPanel class="panel connected-campus"><img :src="objects.find(o=>o.id===selectedInstitute?.objectId)?.image" alt=""/><h3>Кампус подразделения</h3><p>{{objects.find(o=>o.id===selectedInstitute?.objectId)?.address}}</p><UiButton class="btn" @click="detailTab='campus'">Открыть инфраструктуру <Icon name="arrow"/></UiButton></UiPanel></div><UiButton class="btn primary" @click="openAdmissions(selectedInstitute.id)">Перейти к аналитике приёма <Icon name="right" :size="16"/></UiButton></template><template v-if="detailTab==='admissions'"><h3>Программы в рейтингах приёма</h3><UiButton class="quota-row action-row" v-for="p in a.programs.filter(p=>p.institute===selectedInstitute?.short)" :key="p.name+p.metric" @click="openProgram(p)"><span>{{p.name}}</span><b>{{fmt(p.value)}} {{p.metric==='score'?'балла':p.metric==='competition'?'чел./место':'заявлений'}}</b><Icon name="arrow"/></UiButton><h3 v-if="a.newPrograms.some(p=>p.institute===selectedInstitute?.short)">Новые программы</h3><UiButton class="quota-row action-row" v-for="p in a.newPrograms.filter(p=>p.institute===selectedInstitute?.short)" :key="p.name" @click="openProgram(p)"><span>{{p.name}}<small class="program-level">{{p.level}}</small></span><Icon name="arrow"/></UiButton><p v-if="!a.programs.some(p=>p.institute===selectedInstitute?.short)" class="empty">Подразделение не входит в опубликованные топ-5. Общие показатели приёма представлены выше.</p></template><template v-if="detailTab==='campus'"><UiButton class="campus-link" @click="openObject(objects.find(o=>o.id===selectedInstitute?.objectId)!)"><img :src="objects.find(o=>o.id===selectedInstitute?.objectId)?.image" alt=""/><div><h3>{{objects.find(o=>o.id===selectedInstitute?.objectId)?.name}}</h3><p>{{objects.find(o=>o.id===selectedInstitute?.objectId)?.address}}</p></div><Icon name="arrow"/></UiButton></template><div class="detail-actions"><UiButton variant="secondary" @click="openTopic('new-programs')">Новые образовательные программы <Icon name="right"/></UiButton></div></div></template>
<template v-else-if="selectedEvent"><div class="event-modal-hero"><Icon name="calendar" :size="42"/><span>130 ЛЕТ РУТ (МИИТ)</span><b>{{selectedEvent.dateLabel}}</b></div><div class="modal-body"><UiBadge class="badge">{{selectedEvent.category}}</UiBadge><h2>{{selectedEvent.title}}</h2><p class="location-line"><Icon name="pin" :size="17"/>{{selectedEvent.location}}</p><p>{{selectedEvent.description}}</p><div v-if="selectedEvent.participants.length" class="info-box"><Icon name="users"/><p>В программе: {{selectedEvent.participants.join(', ')}}</p></div><div class="info-box"><Icon name="calendar"/><p>2026 год · {{selectedEvent.start?'Время проведения уточняется.':'Точная дата уточняется.'}}</p></div><UiButton class="btn" @click="closeModal();go('calendar')">Открыть календарь <Icon name="right" :size="16"/></UiButton><div class="detail-actions"><UiButton v-if="selectedEvent.id==='military'" variant="secondary" @click="openObject(objects.find(o=>o.id==='military')!)">Карточка объекта <Icon name="right"/></UiButton><UiButton v-if="selectedEvent.id==='drone'" variant="secondary" @click="openTopic('bas')">Развитие БАС <Icon name="right"/></UiButton></div></div></template>

</UiDialog>
</template>
